####### # Setup #######
($x, $y) = random_subset(2, 2..9); $C = lcm($x,$y); $A = $C/$x; $B = $C/$y; Context()->variables->add(y => 'Real'); Context()->noreduce('(-x)-y', '(-x)+y'); $left = Formula("$A x + $B y")->reduce; $right = Formula("$C"); $xi = Point($x,0); $yi = Point(0,$y); Context("Point"); Context()->flags->set(reduceConstants=>0); $xi=Compute("($x,0)"); $yi=Compute("(0,$y)"); $gt = GraphTool("{line, solid, $xi, $yi}, {point, $xi}, {point, $yi}")->with( bBox => [-11, 11, 11, -11], availableTools => [ "PointTool", "LineTool" ], showInStatic => 0, );
############################# # Exercise Group Introduction #############################
BEGIN_PGML Plot the given standard form linear equation.
END_PGML
###### # Body ######
BEGIN_PGML [@KeyboardInstructions('Plot the [`x`]\- and [`y`]-intercepts, as well as the line.')@]**
[`[$left]=[$right]`]
[_]{$gt}{1}
END_PGML
